// ─── Modifier ici si votre Supabase a une autre clé ─────────────────────────
const CONFIG = {
  SUPABASE_URL: 'http://host.docker.internal:8000/rest/v1',
  SUPABASE_KEY: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyAgCiAgICAicm9sZSI6ICJhbm9uIiwKICAgICJpc3MiOiAic3VwYWJhc2UtZGVtbyIsCiAgICAiaWF0IjogMTY0MTc2OTIwMCwKICAgICJleHAiOiAxNzk5NTM1NjAwCn0.dc_X5iR_VP_qT0zsiyj_I_OZ2T9FtRU2BBNWN8Bu4GE',
  OLLAMA_URL: 'http://host.docker.internal:11434',
  FRUGALISTE_MODEL: 'mistral',
  EMBEDDING_MODEL: 'nomic-embed-text'
};
const body = $input.all()[0].json.body || $input.all()[0].json;
return [{ json: { ...CONFIG, _input: body } }];

const cfg = $input.all()[0].json;
const body = cfg._input || {};
const sessionId = body.session_id || null;
const role = body.role || 'prêtre';
const message = (body.message || '').trim();
const tour = Number(body.tour) || 0;
const isInit = tour === 0;
const modeleStandard = body.modele_standard || 'mistral';
return [{
  json: {
    SUPABASE_URL: cfg.SUPABASE_URL,
    SUPABASE_KEY: cfg.SUPABASE_KEY,
    OLLAMA_URL: cfg.OLLAMA_URL,
    FRUGALISTE_MODEL: cfg.FRUGALISTE_MODEL,
    EMBEDDING_MODEL: cfg.EMBEDDING_MODEL,
    session_id: sessionId,
    role: role,
    message: message,
    tour: tour,
    isInit: isInit,
    modele_standard: modeleStandard
  }
}];

const resp = $input.all()[0].json;
const sessionData = Array.isArray(resp) ? resp[0] : resp;
const init = $('Code: Valider & Init').all()[0].json;
return [{
  json: {
    SUPABASE_URL: init.SUPABASE_URL,
    SUPABASE_KEY: init.SUPABASE_KEY,
    OLLAMA_URL: init.OLLAMA_URL,
    FRUGALISTE_MODEL: init.FRUGALISTE_MODEL,
    EMBEDDING_MODEL: init.EMBEDDING_MODEL,
    session_id: sessionData.id,
    role: init.role,
    message: init.message,
    tour: init.tour,
    isInit: true,
    modele_standard: init.modele_standard
  }
}];

const state = $('Merge: Après Init').all()[0].json;
const queryText = state.message || 'frugalité sobriété décroissance introduction';
return [{ json: { ...state, embed_query: queryText } }];

const QUESTIONS = [{id:1,texte:`IA et gestion des ressources`,reponses:[{t:`Automatiser des processus à grande échelle`,p:4},{t:`Contribuer à de nouvelles formes de régulation`,p:3},{t:`Effets inattendus sur l'organisation sociale`,p:2},{t:`Encourager d'autres priorités de gestion`,p:1}]},{id:2,texte:`Agriculture de précision / drones`,reponses:[{t:`Oui, optimiser via technologie`,p:4},{t:`Oui, si accompagné d'agroécologie`,p:3},{t:`Non, agriculture industrielle est le problème`,p:2},{t:`Non, circuits courts et local`,p:1}]},{id:3,texte:`Villes intelligentes / IoT`,reponses:[{t:`Oui, optimiser trafic/éclairage via tech`,p:4},{t:`Oui, mais espaces verts et mobilité douce`,p:3},{t:`Non, décroissance planifiée nécessaire`,p:2},{t:`Non, architecture durable d'abord`,p:1}]},{id:4,texte:`Fusion nucléaire`,reponses:[{t:`Oui, source illimitée et propre`,p:4},{t:`Oui, mais sobriété immédiate en attendant`,p:3},{t:`Non, délais trop longs, détourne des solutions`,p:2},{t:`Non, remettre en cause la croissance infinie`,p:1}]},{id:5,texte:`Fast fashion / économie circulaire`,reponses:[{t:`Oui, l'économie circulaire perpétue ce modèle à faible impact`,p:4},{t:`Oui, mais il faut aussi acheter moins`,p:3},{t:`Non, il faut produire et acheter beaucoup moins`,p:2},{t:`Non, ce modèle doit être démantelé, pas "verdi"`,p:1}]},{id:6,texte:`Carburants verts / avion`,reponses:[{t:`Oui, maintenir la mobilité aérienne sans culpabilité`,p:4},{t:`Oui, mais technologies chères et rares`,p:3},{t:`Non, taxe kérosène et réduction des vols`,p:2},{t:`Non, voyager moins et moins loin`,p:1}]},{id:7,texte:`Sobriété vs efficacité`,reponses:[{t:`Non, l'efficacité réduit l'impact sans toucher au confort`,p:4},{t:`Les deux sont complémentaires`,p:3},{t:`Oui, sans sobriété les gains d'efficacité sont annulés`,p:2},{t:`Oui, l'efficacité est un leurre`,p:1}]},{id:8,texte:`Choix individuels vs collectif`,reponses:[{t:`Oui, le marché répondra aux consommateurs éclairés`,p:4},{t:`Oui, mais amplifiée par des politiques publiques fortes`,p:3},{t:`Non, la responsabilité est collective et politique`,p:2},{t:`Non, c'est un piège qui occulte le pouvoir des entreprises`,p:1}]},{id:9,texte:`Taxe billets d'avion`,reponses:[{t:`Non, développer d'abord avions à hydrogène/électriques`,p:4},{t:`Non, cela limiterait la liberté de mouvement`,p:3},{t:`Oui, mais si les recettes financent des alternatives`,p:2},{t:`Oui, moyen efficace de réduire les émissions`,p:1}]},{id:10,texte:`Interdiction voitures thermiques 2030`,reponses:[{t:`Non, développer d'abord carburants synthétiques/hydrogène`,p:4},{t:`Non, cela pénaliserait les ménages modestes`,p:3},{t:`Oui, mais si alternatives accessibles proposées`,p:2},{t:`Oui, mesure forte pour réduire la pollution`,p:1}]},{id:11,texte:`Subventions recherche technologies vertes`,reponses:[{t:`Oui, seul moyen d'accélérer la transition`,p:4},{t:`Oui, mais en ciblant les technologies prometteuses`,p:3},{t:`Non, réduire d'abord la consommation`,p:2},{t:`Non, le marché doit décider`,p:1}]},{id:12,texte:`Interdiction pub produits polluants`,reponses:[{t:`Non, éduquer plutôt qu'interdire`,p:4},{t:`Non, atteinte à la liberté d'expression`,p:3},{t:`Oui, mais seulement pour les produits les plus émetteurs`,p:2},{t:`Oui, la publicité encourage la surconsommation`,p:1}]},{id:13,texte:`Mobilité partagée`,reponses:[{t:`Oui, optimise l'utilisation des véhicules`,p:4},{t:`Oui, mais avec réduction de la demande`,p:3},{t:`Non, peut encourager plus d'usage`,p:2},{t:`Non, réduire la dépendance automobile d'abord`,p:1}]},{id:14,texte:`Capture carbone DAC`,reponses:[{t:`Oui, capture le CO2 directement de l'atmosphère`,p:4},{t:`Oui, mais développée durablement`,p:3},{t:`Non, coûteuse et énergivore`,p:2},{t:`Non, réduire les émissions à la source d'abord`,p:1}]},{id:15,texte:`Course techno détourne l'attention`,reponses:[{t:`Non, innovations essentielles sans changer nos comportements`,p:4},{t:`Non, maintenir la croissance tout en réduisant les émissions`,p:3},{t:`Oui, mais certaines technologies utiles en complément`,p:2},{t:`Oui, illusion que la tech résout tout`,p:1}]},{id:16,texte:`Nanotechnologies et climat`,reponses:[{t:`Oui, solutions innovantes pour capturer le carbone`,p:4},{t:`Oui, mais développées de manière responsable`,p:3},{t:`Non, risques pour l'environnement et la santé`,p:2},{t:`Non, réduire la consommation énergétique d'abord`,p:1}]},{id:17,texte:`Transports doux (vélo, marche)`,reponses:[{t:`Non, la rapidité est essentielle`,p:4},{t:`Non, améliorer plutôt les transports motorisés via la tech`,p:3},{t:`Oui, mais intégré dans une politique multimodale`,p:2},{t:`Oui, écologiques et favorisent la santé`,p:1}]},{id:18,texte:`Renoncer aux conforts modernes`,reponses:[{t:`Non, le progrès ne doit pas être remis en question`,p:4},{t:`Non, rendre ces conforts plus écologiques via la tech`,p:3},{t:`Oui, mais progressivement et équitablement`,p:2},{t:`Oui, le confort matériel a un coût environnemental élevé`,p:1}]},{id:19,texte:`Plateformes numériques et conso responsable`,reponses:[{t:`Oui, mieux informer et orienter les consommateurs`,p:4},{t:`Oui, mais transparentes et régulées`,p:3},{t:`Non, incitent à la surconsommation`,p:2},{t:`Non, réduire leur usage, privilégier les circuits courts`,p:1}]},{id:20,texte:`Investissements startups climatiques`,reponses:[{t:`Oui, agiles et innovantes, transforment les secteurs`,p:4},{t:`Oui, mais encadrées contre les dérives commerciales`,p:3},{t:`Non, motivées par le profit plus que l'écologie`,p:2},{t:`Non, transition portée par le public et le collectif`,p:1}]},{id:21,texte:`Géo-ingénierie`,reponses:[{t:`Oui, nécessaire pour compenser les émissions résiduelles`,p:4},{t:`Oui, mais uniquement comme solution d'appoint`,p:3},{t:`Non, trop risqué et incertain`,p:2},{t:`Non, fuite en avant qui détourne de la réduction réelle`,p:1}]},{id:22,texte:`IA et transition écologique`,reponses:[{t:`Oui, optimise production, transports, consommation`,p:4},{t:`Oui, mais si l'IA est elle-même sobre en énergie`,p:3},{t:`Non, augmente la consommation d'énergie et de ressources`,p:2},{t:`Non, priorités sociales et comportementales avant tout`,p:1}]},{id:23,texte:`Comportements individuels / impact réel`,reponses:[{t:`Oui, chaque geste compte et entraîne un changement collectif`,p:4},{t:`Oui, mais soutenus par des politiques publiques ambitieuses`,p:3},{t:`Non, marginaux face à l'empreinte industrielle`,p:2},{t:`Non, distraction du vrai problème structurel`,p:1}]},{id:24,texte:`Smart cities`,reponses:[{t:`Oui, réduit gaspillages et améliore l'efficacité énergétique`,p:4},{t:`Oui, si les technologies servent citoyens et environnement`,p:3},{t:`Non, ne s'attaque pas à la surconsommation ni à l'artificialisation`,p:2},{t:`Non, illusion technologique qui perpétue le modèle`,p:1}]}];
const state = $('Merge: Après Init').all()[0].json;

const rawHistory = $('HTTP: Récupérer Historique').all();
let history = [];
if (rawHistory.length > 0) { const h = rawHistory[0].json; history = Array.isArray(h) ? h : []; }
const rawScores = $('HTTP: Récupérer Scores').all();
let scores = [];
if (rawScores.length > 0) { const s = rawScores[0].json; scores = Array.isArray(s) ? s : []; }
const rawRag = $('HTTP: Recherche RAG').all();
let ragChunks = [];
if (rawRag.length > 0 && !rawRag[0].json.error) {
  const r = rawRag[0].json; ragChunks = Array.isArray(r) ? r : [];
}

const posedIds = scores.map(s => s.question_id);
const nextQ = QUESTIONS.find(q => !posedIds.includes(q.id)) || null;
const scorePartiel = scores.reduce((sum, s) => sum + (s.points || 0), 0);
const chunksText = ragChunks.map(c => c.contenu).join('\n\n---\n\n') || '(base de connaissances non encore chargee)';
const historyText = history.map(m => '[' + m.auteur.toUpperCase() + ']: ' + m.contenu).join('\n') || '(debut de la conversation)';
const nextQTexte = nextQ ? nextQ.texte : 'Toutes les questions ont ete posees. Conclus en synthetisant les positions.';

const questionnaireRefDisplay = QUESTIONS.map(q =>
  'Q' + q.id + ' - ' + q.texte + ':\n' + q.reponses.map((r, i) => '  ' + 'ABCD'[i] + ') ' + r.t).join('\n')
).join('\n\n');

const choices4 = nextQ ? nextQ.reponses.map((r, i) => 'ABCD'[i] + ') ' + r.t).join('\n') : '';
const choices4Scoring = nextQ ? nextQ.reponses.map((r, i) => 'ABCD'[i] + ') ' + r.t + ' -> ' + r.p + ' pts').join('\n') : '';

const isFirstMessage = history.length === 0;

const debateContext = isFirstMessage
  ? "Tu vas ouvrir le debat en prenant ton role. Tu te presentes naturellement dans ta posture de " + state.role + " (sans jamais mentionner que tu es une IA), tu poses le contexte depuis ta perspective frugaliste."
  : "Tu es en debat. Tu challenges les positions de ton interlocuteur de facon argumentee et fluide. Tu ne mentionnes jamais que tu es une IA.";

const nextQInstruction = isFirstMessage
  ? "Dans ton message d'ouverture, apres t'etre presente, pose naturellement cette premiere question et presente les 4 choix de reponse exactement comme ci-dessous (une par ligne) :\nQuestion : " + nextQTexte + "\n" + choices4
  : "Dans ta replique, pose naturellement cette question et presente les 4 choix exactement comme ci-dessous (une par ligne) :\nQuestion : " + nextQTexte + "\n" + choices4;

const systemPrompt = "Tu es une intelligence artificielle dont la vision du monde est profondement frugaliste et decroissante.\n\n"
  + "Tu incarnes le role suivant : " + state.role + ".\n"
  + "Tu t'exprimes exclusivement depuis ce role. Tu ne sors jamais de ce role.\n\n"
  + "Base de connaissances frugaliste :\n" + chunksText + "\n\n"
  + debateContext + "\n\n"
  + "Regles absolues pour le questionnaire :\n"
  + "- Une seule question par message\n"
  + "- Ne jamais annoncer qu'il y a un questionnaire ni mentionner les scores\n"
  + "- Presenter les 4 choix (A/B/C/D) apres la question, tels quels\n"
  + "- Attendre la reponse avant la question suivante\n\n"
  + "Questionnaire de reference :\n" + questionnaireRefDisplay + "\n\n"
  + "Questions deja posees : " + (posedIds.length > 0 ? posedIds.join(', ') : 'aucune') + "\n"
  + nextQInstruction + "\n\n"
  + "Historique :\n" + historyText;

const scoringPrompt = nextQ
  ? "Analyse si le message suivant repond a la question Q" + nextQ.id + ".\n\n"
    + "Message :\n" + (state.message || '(aucun)') + "\n\n"
    + "Question : " + nextQTexte + "\n"
    + "Options :\n" + choices4Scoring + "\n\n"
    + "JSON uniquement : {\"question_id\": " + nextQ.id + ", \"points\": X, \"reponse_detectee\": \"A\"} ou {\"question_id\": null}"
  : "{\"question_id\": null}";

const userContent = isFirstMessage
  ? "Ouvre le debat dans ton role de " + state.role + ". Presente-toi, pose le contexte et engage avec ta premiere question."
  : (state.message || 'Reponds a ton interlocuteur.');

return [{
  json: {
    ...state,
    system_prompt: systemPrompt,
    scoring_prompt: scoringPrompt,
    user_content: userContent,
    scores: scores,
    score_partiel: scorePartiel,
    questions_repondues: posedIds.length,
    questions_restantes: 24 - posedIds.length,
    posed_ids: posedIds,
    next_question: nextQ,
    rag_chunks: ragChunks,
    frugaliste_messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  }
}];

const classifResp = $input.all()[0].json;
const state = $('Code: Construire Prompt').all()[0].json;
const frugResp = $('HTTP: Appeler LLM Frugaliste').all()[0].json;

const frugText = (frugResp.message && frugResp.message.content) ? frugResp.message.content : '';

// Parser la réponse du classificateur
let scoring = { question_id: null, points: null, reponse_detectee: null };
try {
  const rawContent = (classifResp.message && classifResp.message.content) ? classifResp.message.content : '';
  const match = rawContent.match(/\{[\s\S]*?\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    if (parsed.question_id !== null && parsed.question_id !== undefined) {
      scoring = parsed;
    }
  }
} catch(e) {
  // Scoring non extractible — pas grave, on continue
}

// Calculer le score intermédiaire
const newPoints = (scoring.question_id && scoring.points) ? scoring.points : 0;
const scorePartiel = state.score_partiel + newPoints;
const questionsRepondues = state.questions_repondues + (scoring.question_id ? 1 : 0);

return [{
  json: {
    ...state,
    frugaliste_response: frugText,
    scoring: scoring,
    score_partiel: scorePartiel,
    questions_repondues: questionsRepondues,
    questions_restantes: 24 - questionsRepondues,
    fin_session: questionsRepondues >= 24
  }
}];

// Récupérer l'état depuis Code: Parser Score & État (source de vérité)
const state = $('Code: Parser Score & État').all()[0].json;
return [{ json: state }];

const PROFILS = [
  {min:24,max:42,nom:'Souveraineté et sobriété radicales',desc:'Rejet de la technologie comme solution, transformation profonde des modes de vie, décroissance et relocalisation'},
  {min:43,max:60,nom:'Régulation et changement de cap',desc:'Technologie comme outil subordonné à une sobriété forte, régulation et planification écologique prioritaires'},
  {min:61,max:78,nom:'Pragmatisme et mix équilibré',desc:'Mix technologie + évolutions sociétales, approche tous azimuts'},
  {min:79,max:96,nom:'Confiance technologique et innovation',desc:'Forte confiance dans le progrès technique pour découpler prospérité et impact'}
];

const state = $input.all()[0].json;
const profil = PROFILS.find(p => state.score_partiel >= p.min && state.score_partiel <= p.max) || PROFILS[2];

const chunksText = (state.rag_chunks || []).map(c => c.contenu).join('\n\n---\n\n') || '(utilise tes connaissances générales du frugalisme)';

const finPromptSystem = `Tu as mené la conversation jusqu'à son terme. Ton interlocuteur a répondu à l'ensemble du questionnaire.\n\nRésultat :\n- Score total : ${state.score_partiel}/96\n- Profil : ${profil.nom}\n- Description : ${profil.desc}\n\nDans ton rôle de ${state.role}, tu vas :\n1. Révéler ce résultat de façon naturelle et bienveillante, sans jamais mentionner qu'il s'agissait d'un questionnaire noté\n2. Proposer des pistes concrètes pour évoluer vers plus de frugalité, en t'appuyant sur ta base de connaissances et en restant dans ton personnage\n\nExtraits de ta base de connaissances pour guider tes conseils :\n${chunksText}`;

return [{
  json: {
    ...state,
    profil: profil,
    score_final: state.score_partiel,
    fin_messages: [
      { role: 'system', content: finPromptSystem },
      { role: 'user', content: 'Conclus la conversation de façon mémorable dans ton rôle.' }
    ]
  }
}];

const llmResp = $input.all()[0].json;
const state = $('Code: Préparer Message Final').all()[0].json;
const finalText = (llmResp.message && llmResp.message.content) ? llmResp.message.content : state.frugaliste_response;
return [{ json: { ...state, final_message: finalText } }];

// Récupérer l'état — depuis la branche fin ou la branche normale
let state;
try {
  state = $('Code: Extraire Message Final').all()[0].json;
} catch(e) {
  state = $('Code: État Final Avant Réponse').all()[0].json;
}

const message = state.final_message || state.frugaliste_response || '';

return [{
  json: {
    session_id: state.session_id,
    message: message,
    score_partiel: state.score_partiel || 0,
    questions_repondues: state.questions_repondues || 0,
    questions_restantes: state.questions_restantes || 24,
    derniere_question_scoree: (state.scoring && state.scoring.question_id) ? state.scoring.question_id : null,
    fin_session: state.fin_session || false,
    profil: state.fin_session ? (state.profil ? state.profil.nom : null) : null
  }
}];
